<script setup lang="ts">import { ref } from 'vue';import { post } from '../../api/client';import AsyncState from '../../components/AsyncState.vue';const path=ref(''),data=ref<any>(),error=ref(''),loading=ref(false);async function register(){loading.value=true;try{const source:any=await post('/import-sources',{path:path.value});data.value=await post('/import-sources/profile',{source_id:source.resource_id})}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{loading.value=false}}</script>
<template><section class="panel"><div class="panel-head"><div><h2>Historical import</h2><p>Bounded read, profile, map, normalize, reject, and content-address.</p></div></div><div class="inline"><input v-model="path" placeholder="Allowed server-side CSV/JSONL/Parquet path"><button @click="register">Register & profile</button></div><AsyncState :loading="loading" :error="error" :empty="!data"><pre>{{data}}</pre></AsyncState></section></template>
